data class Post(
    val id: String,
    val username: String,
    val location: String,
    val caption: String,
    val avatarUrl: String,
    val imageUrl: String,
    val likes: Int,
    val minutesAgo: Int
)

private enum class Screen {
    FEED, CAMERA
}

@OptIn(ExperimentalMaterialApi::class)
@Composable
fun InstagramCloneApp() {
    var currentScreen by remember { mutableStateOf(Screen.FEED) }

    when (currentScreen) {
        Screen.FEED -> FeedScreen(
            onOpenCamera = { currentScreen = Screen.CAMERA }
        )

        Screen.CAMERA -> CameraScreen(
            onBack = { currentScreen = Screen.FEED }
        )
    }
}

