        child: Stack(
          children: [
            // Main feed
            RefreshIndicator(
              key: _refreshIndicatorKey,
              color: Colors.white,
              backgroundColor: Colors.black,
              onRefresh: _refreshPosts,
              child: CustomScrollView(
                controller: _scrollController,
                slivers: [
                  // Stories Section
