class InstagramHomePage extends StatefulWidget {
  const InstagramHomePage({super.key});

  @override
  State<InstagramHomePage> createState() => _InstagramHomePageState();
}

class _InstagramHomePageState extends State<InstagramHomePage> {
  final List<Post> _posts = [];
  bool _isLoading = false;
  bool _hasMore = true;
  int _currentPage = 1;
  final ScrollController _scrollController = ScrollController();
  final GlobalKey<RefreshIndicatorState> _refreshIndicatorKey =
      GlobalKey<RefreshIndicatorState>();

  // Camera related
  File? _capturedImage;
  bool _showCameraView = false;

  @override
  void initState() {
    super.initState();
    _fetchPosts();
    _scrollController.addListener(_onScroll);
  }

  @override
  void dispose() {
    _scrollController.dispose();
    super.dispose();
  }

  void _onScroll() {
    if (_scrollController.position.pixels >=
            _scrollController.position.maxScrollExtent - 200 &&
        !_isLoading &&
        _hasMore) {
      _fetchMorePosts();
    }
  }

  Future<void> _fetchPosts({bool isRefresh = false}) async {
    if (isRefresh) {
      setState(() {
        _currentPage = 1;
        _posts.clear();
        _hasMore = true;
      });
    }

    if (_isLoading) return;
    setState(() {
      _isLoading = true;
    });

    try {
      final response = await http.get(
        Uri.parse('https://picsum.photos/v2/list?page=$_currentPage&limit=10'),
      );

      if (response.statusCode == 200) {
        final List<dynamic> data = json.decode(response.body);
        final List<Post> newPosts = data.map((item) => Post.fromJson(item)).toList();

        setState(() {
          if (isRefresh) {
            _posts.clear();
          }
          _posts.addAll(newPosts);
          _hasMore = newPosts.length == 10;
        });
      } else {
        _showErrorSnackBar('Failed to load posts');
      }
    } catch (e) {
      _showErrorSnackBar('Error: ${e.toString()}');
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

  Future<void> _fetchMorePosts() async {
    if (_isLoading || !_hasMore) return;
    _currentPage++;
    await _fetchPosts();
  }

  Future<void> _refreshPosts() async {
    _currentPage = 1;
    await _fetchPosts(isRefresh: true);
  }

  void _showErrorSnackBar(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message), backgroundColor: Colors.red),
    );
  }

  Future<void> _openCamera() async {
    try {
      final ImagePicker picker = ImagePicker();
      final XFile? image = await picker.pickImage(
        source: ImageSource.camera,
        preferredCameraDevice: CameraDevice.rear,
      );

      if (image != null) {
        setState(() {
          _capturedImage = File(image.path);
          _showCameraView = true;
        });

        // Automatically hide camera view after 3 seconds
        Future.delayed(const Duration(seconds: 3), () {
          if (mounted && _showCameraView) {
            setState(() {
              _showCameraView = false;
            });
          }
        });
      }
    } catch (e) {
      _showErrorSnackBar('Error opening camera: ${e.toString()}');
    }
  }

  void _onSwipeLeft() {
    _openCamera();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      appBar: AppBar(
