                            return const Center(
                              child: Padding(
                                padding: EdgeInsets.all(16.0),
                                child: Text(
                                  'No more posts',
                                  style: TextStyle(color: Colors.grey),
                                ),
                              ),
                            );
                          }
                        }
                        return _buildPostCard(_posts[index]);
                      },
                      childCount: _posts.length + 1,
                    ),
                  ),
                ],
              ),
            ),

            // Camera overlay when image is captured
            if (_showCameraView && _capturedImage != null)
              Container(
