class Post {
  final String id;
  final String author;
  final String downloadUrl;
  final int likesCount;
  final int commentsCount;
  final String caption;
  final String timeAgo;

  Post({
    required this.id,
    required this.author,
    required this.downloadUrl,
    required this.likesCount,
    required this.commentsCount,
    required this.caption,
    required this.timeAgo,
  });

  factory Post.fromJson(Map<String, dynamic> json) {
    return Post(
      id: json['id'].toString(),
      author: 'user_${json['author'] ?? json['id']}',
      downloadUrl: json['download_url'] ?? json['url'],
      likesCount: (int.parse(json['id'].toString()) % 500) + 100,
      commentsCount: (int.parse(json['id'].toString()) % 50) + 5,
      caption: _getRandomCaption(int.parse(json['id'].toString())),
      timeAgo: '${(int.parse(json['id'].toString()) % 23) + 1} HOURS AGO',
    );
  }

  static String _getRandomCaption(int seed) {
    List<String> captions = [
      'Amazing view! 😍',
      'Living my best life ✨',
      'Weekend vibes 🎉',
      'Feeling blessed 🙏',
      'New adventure 🌟',
      'Just another day in paradise 🌴',
      'Making memories 📸',
      'Good times and tan lines ☀️',
      'Chasing sunsets 🌅',
      'Happiness is a journey 🚀',
    ];
    return captions[seed % captions.length];
  }
}
